{
  "geracao_sequencia_aleatoria": {
    "julgamento": "Low",
    "justificativa": "O artigo relata que os pacientes foram alocados aleatoriamente em proporção 1:1 utilizando uma lista gerada por computador."
  },
  "ocultacao_alocacao": {
    "julgamento": "Unclear",
    "justificativa": "O método utilizado para ocultar a lista de randomização antes da indução da anestesia não é descrito, apenas que um membro da equipe avaliou a lista antes da indução."
  },
  "cegamento_participantes_equipe": {
    "julgamento": "High",
    "justificativa": "A intervenção (terapia hemodinâmica guiada por algoritmo vs. cuidados padrão) é intrinsecamente aberta para a equipe de anestesia/intensiva e os pacientes, embora o monitor fosse coberto no grupo controle."
  },
  "cegamento_avaliadores_desfecho": {
    "julgamento": "Low",
    "justificativa": "O desfecho primário (creatinina sérica) é objetivo e baseado em laboratório, e os dados foram coletados por uma equipe de pesquisa separada da equipe tratante, sugerindo baixo risco de viés na medição."
  },
  "dados_desfecho_incompletos": {
    "julgamento": "Low",
    "justificativa": "Os dados de mortalidade e desfechos principais estão disponíveis para a grande maioria dos pacientes, com exclusões justificadas por não recebimento da intervenção (quebra de protocolo) e análise em intenção de tratamento implícita."
  },
  "relato_seletivo": {
    "julgamento": "Low",
    "justificativa": "O registro do ensaio na ClinicalTrials.gov é citado e todos os desfechos predefinidos e exploratórios são reportados nos resultados."
  },
  "outros_vieses": {
    "julgamento": "Unclear",
    "justificativa": "Não há evidência explícita de outros vieses sistêmicos além da possível influência do conhecimento do estudo sobre a equipe, que não pode ser totalmente quantificada."
  },
  "risco_global": {
    "julgamento": "High",
    "justificativa": "O risco de viés global é considerado alto devido ao alto risco de viés de desempenho/detecção inerente à natureza da intervenção hemodinâmica que não pode ser cegada para a equipe tratante."
  }
}
